function getLanguage(){try{const saved=localStorage.getItem('sdd-language');if(saved)return saved}catch(e){}const cookie=document.cookie.match(/(?:^|; )sdd-language=([^;]+)/);return cookie?decodeURIComponent(cookie[1]):null}
function setLanguage(lang){try{localStorage.setItem('sdd-language',lang)}catch(e){}document.cookie=`sdd-language=${encodeURIComponent(lang)}; max-age=31536000; path=/`}
const modules={fa:[['01','تعریف SDD','چرا مشخصات می‌توانند کیفیت تصمیم‌گیری را بهتر کنند؟','pages/sdd-introduction.html'],['02','انواع و ابزارها','Spec-first، Spec-anchored و Spec-as-source را مقایسه کن','#'],['03','مزایا و محدودیت‌ها','از traceability تا هزینهٔ نگهداری Spec','#'],['04','SDD در برابر Markdown','چرا SDD فقط مستندسازی نیست؟','#'],['05','مثال‌های عملی','یک نیازمندی را تا تست دنبال کن','#'],['06','آزمون تعاملی','مدل ذهنی خودت را بسنج','#']],en:[['01','Define SDD','See how specifications improve decision quality.','pages/sdd-introduction.html'],['02','Types and tools','Compare spec-first, spec-anchored, and spec-as-source.','#'],['03','Benefits and limits','From traceability to the cost of maintaining specs.','#'],['04','SDD versus Markdown','Why SDD is more than documentation.','#'],['05','Practical examples','Follow a requirement all the way to a test.','#'],['06','Knowledge check','Test your mental model.','#']]};
